// commonDir is the git directory, or the directory its commondir file
// names, as in a linked worktree (gitrepository-layout).
func commonDir(gitFS billy.Filesystem) (string, error) {
	gitDir := gitFS.Root()
	b, err := util.ReadFile(gitFS, "commondir")
	if errors.Is(err, os.ErrNotExist) {
		return gitDir, nil
	}
	if err != nil {
		return "", fmt.Errorf("read commondir: %w", err)
	}

	dir := strings.TrimSpace(string(b))
	if !filepath.IsAbs(dir) {
		dir = filepath.Join(gitDir, dir)
	}
	return filepath.Clean(dir), nil
}

func discoverRoot(cwd string) (string, error) {
	r, err := open(cwd, true)
	if err != nil {
		return "", err
	}
	return r.Root, nil
}

func sameDir(a, b string) bool {
	ai, errA := os.Stat(a)
	bi, errB := os.Stat(b)
	if errA != nil || errB != nil {
		return filepath.Clean(a) == filepath.Clean(b)
	}
	return os.SameFile(ai, bi)
}

// Package store implements gittuf's gitstore.Storer over go-git, read-only.
//
// Every write method returns ErrReadOnly, so no gittuf code path reached
// through this store can modify the repository. The read methods mirror the
// semantics of gittuf's git binary backed gitinterface.Repository, and the
// object reads follow gittuf's own go-git backend (internal/gogitstore in the
// pjbgf/gittuf fork, Apache-2.0). Tests compare both implementations on the
// same repositories.
